import { useState, useEffect } from 'react';
import API from '../services/api';

const ACTIONS = ['', 'LOGIN', 'LOGOUT', 'UPLOAD', 'DELETE', 'DOWNLOAD', 'UPDATE', 'VIEW', 'RESTORE'];

const ACTION_COLORS = {
  LOGIN: '#2e7d32', LOGOUT: '#555', UPLOAD: '#1565c0',
  DELETE: '#c62828', DOWNLOAD: '#00695c', UPDATE: '#e65100',
  VIEW: '#6a1b9a', RESTORE: '#f57f17'
};

export default function AuditLogs() {
  const [logs, setLogs] = useState([]);
  const [pagination, setPagination] = useState({ page: 1, pages: 1, total: 0 });
  const [action, setAction] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchLogs = async (page = 1) => {
    setLoading(true);
    try {
      const params = { page, limit: 20 };
      if (action) params.action = action;
      const { data } = await API.get('/audit', { params });
      setLogs(data.logs);
      setPagination({ page: data.page, pages: data.pages, total: data.total });
    } catch {}
    setLoading(false);
  };

  useEffect(() => { fetchLogs(1); }, [action]);

  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Audit Logs</h2>
      <div style={styles.filterRow}>
        <select style={styles.select} value={action} onChange={e => setAction(e.target.value)}>
          {ACTIONS.map(a => <option key={a} value={a}>{a || 'All Actions'}</option>)}
        </select>
        <span style={{ color: '#666', fontSize: '13px' }}>Total: {pagination.total} logs</span>
      </div>

      {loading ? <p>Loading...</p> : (
        <table style={styles.table}>
          <thead>
            <tr style={styles.thead}>
              <th style={styles.th}>User</th>
              <th style={styles.th}>Action</th>
              <th style={styles.th}>Resource</th>
              <th style={styles.th}>Details</th>
              <th style={styles.th}>IP</th>
              <th style={styles.th}>Timestamp</th>
            </tr>
          </thead>
          <tbody>
            {logs.map(log => (
              <tr key={log._id} className="table-row" style={styles.tr}>
                <td style={styles.td}>{log.userName || log.user?.name || '-'}</td>
                <td style={styles.td}>
                  <span style={{ ...styles.badge, background: ACTION_COLORS[log.action] || '#555' }}>{log.action}</span>
                </td>
                <td style={styles.td}>{log.resource || '-'}</td>
                <td style={styles.td}>{log.details || '-'}</td>
                <td style={styles.td}>{log.ipAddress || '-'}</td>
                <td style={styles.td}>{new Date(log.createdAt).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <div style={styles.pagination}>
        {Array.from({ length: pagination.pages }, (_, i) => i + 1).map(p => (
          <button key={p} style={{ ...styles.pageBtn, background: p === pagination.page ? '#1a237e' : '#e8eaf6', color: p === pagination.page ? '#fff' : '#333' }}
            onClick={() => fetchLogs(p)}>{p}</button>
        ))}
      </div>
    </div>
  );
}

const styles = {
  container: { padding: '24px', maxWidth: '1200px', margin: '0 auto' },
  heading: { color: '#1a237e', marginBottom: '16px' },
  filterRow: { display: 'flex', gap: '16px', alignItems: 'center', marginBottom: '16px' },
  select: { padding: '8px', border: '1px solid #ccc', borderRadius: '4px', fontSize: '13px' },
  table: { width: '100%', borderCollapse: 'collapse', background: '#fff', borderRadius: '8px', overflow: 'hidden', boxShadow: '0 1px 6px rgba(0,0,0,0.1)' },
  thead: { background: '#1a237e', color: '#fff' },
  th: { padding: '10px 12px', textAlign: 'left', fontSize: '13px' },
  tr: { borderBottom: '1px solid #eee' },
  td: { padding: '10px 12px', fontSize: '13px' },
  badge: { color: '#fff', padding: '2px 8px', borderRadius: '12px', fontSize: '11px', fontWeight: 'bold' },
  pagination: { display: 'flex', gap: '6px', marginTop: '16px' },
  pageBtn: { padding: '6px 12px', border: 'none', borderRadius: '4px', cursor: 'pointer' }
};
